1	using Microsoft.AspNetCore.DataProtection.EntityFrameworkCore;
2	using Microsoft.EntityFrameworkCore;
3	
4	namespace FutureClassroom.Core.Data;
5	
6	public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options), IDataProtectionKeyContext {
7	    public DbSet<Course> Courses => Set<Course>();
8	    public DbSet<Lesson> Lessons => Set<Lesson>();
9	    public DbSet<Department> Departments => Set<Department>();
10	    public DbSet<AiResult> AiResults => Set<AiResult>();
11	    public DbSet<AiWindow> AiWindows => Set<AiWindow>();
12	    public DbSet<AiWindowSeat> AiWindowSeats => Set<AiWindowSeat>();
13	    public DbSet<DataProtectionKey> DataProtectionKeys => Set<DataProtectionKey>();
14	
15	    protected override void OnModelCreating(ModelBuilder modelBuilder) {
16	        modelBuilder.Entity<Course>(e => {
17	            e.HasKey(c => c.Id);
18	            e.HasIndex(c => c.CourseKey).IsUnique();
19	            e.HasIndex(c => c.Serial);
20	            e.Property(c => c.CourseKey).HasMaxLength(64);
21	            e.Property(c => c.CourseId).HasMaxLength(32);
22	            e.Property(c => c.Serial).HasMaxLength(16);
23	            e.Property(c => c.Semester).HasMaxLength(8);
24	            e.Property(c => c.Section).HasMaxLength(8);
25	            e.Property(c => c.TeacherId).HasMaxLength(32);
26	            e.Property(c => c.ClassroomName).HasMaxLength(32);
27	            e.Property(c => c.BuildingId).HasMaxLength(16);
28	        });
29	
30	        modelBuilder.Entity<Lesson>(e => {
31	            e.HasKey(l => l.Id);
32	            e.HasIndex(l => l.LessonId).IsUnique();
33	            e.HasIndex(l => l.CourseKey);
34	            e.Property(l => l.LessonId).HasMaxLength(64);
35	            e.Property(l => l.CourseKey).HasMaxLength(64);
36	            e.Property(l => l.Status).HasMaxLength(32);
37	            e.HasOne(l => l.Course)
38	                .WithMany(c => c.Lessons)
39	                .HasForeignKey(l => l.CourseKey)
40	                .HasPrincipalKey(c => c.CourseKey);
41	        });
42	
43	        modelBuilder.Entity<Department>(e => {
44	            e.HasKey(d => d.Id);
45	            e.HasIndex(d => d.DeptCode).IsUnique();
46	            e.HasIndex(d => d.NameZh);
47	            e.HasIndex(d => d.ShortNameZh);
48	            e.Property(d => d.DeptCode).HasMaxLength(8);
49	            e.Property(d => d.NameZh).HasMaxLength(512);
50	            e.Property(d => d.NameEn).HasMaxLength(512);
51	            e.Property(d => d.ShortNameZh).HasMaxLength(128);
52	            e.Property(d => d.ShortNameEn).HasMaxLength(128);
53	        });
54	
55	        modelBuilder.Entity<AiResult>(e => {
56	            e.HasKey(r => r.Id);
57	            e.HasIndex(r => r.LessonId).IsUnique();
58	            e.HasIndex(r => r.CourseKey);
59	            e.Property(r => r.LessonId).HasMaxLength(64);
60	            e.Property(r => r.CourseKey).HasMaxLength(64);
61	            e.Property(r => r.Semester).HasMaxLength(8);
62	            e.Property(r => r.CourseId).HasMaxLength(32);
63	            e.Property(r => r.ClassSection).HasMaxLength(8);
64	            e.Property(r => r.Week).HasMaxLength(4);
65	            e.Property(r => r.VideoPath).HasMaxLength(500);
66	        });
67	
68	        modelBuilder.Entity<AiWindow>(e => {
69	            e.HasKey(w => new { w.LessonId, w.WindowIndex });
70	            e.HasIndex(w => w.LessonId);
71	            e.Property(w => w.LessonId).HasMaxLength(64);
72	        });
73	
74	        modelBuilder.Entity<AiWindowSeat>(e => {
75	            e.HasKey(s => new { s.LessonId, s.WindowIndex, s.SeatKey, s.EngagementLevel });
76	            e.HasIndex(s => s.LessonId);
77	            e.HasIndex(s => new { s.LessonId, s.WindowIndex });
78	            e.Property(s => s.LessonId).HasMaxLength(64);
79	            e.Property(s => s.SeatKey).HasMaxLength(16);
80	            e.Property(s => s.GroupKey).HasMaxLength(8);
81	            e.Property(s => s.EngagementLevel).HasMaxLength(8);
82	            e.HasOne<AiWindow>()
83	                .WithMany()
84	                .HasForeignKey(s => new { s.LessonId, s.WindowIndex })
85	                .OnDelete(DeleteBehavior.Cascade);
86	        });
87	    }
88	}
