170	    /// <summary>
171	    /// Fill NameEn for every stored course via https://course.ntu.edu.tw/api/v3/course?semester={semester}&serial={serial}&lang=en_US.
172	    /// </summary>
173	    private async Task SyncEnglishNamesAsync(HttpClient httpClient)
174	    {
175	        await using var db = await _dbFactory.CreateDbContextAsync();
176	        var courses = await db.Courses
177	            .Where(c => !string.IsNullOrEmpty(c.Serial))
178	            .ToListAsync();
179	
180	        foreach (var course in courses)
181	        {
182	            _logger.LogInformation("正在抓取 {CourseKey} 的英文名稱 (serial={Serial})...", course.CourseKey, course.Serial);
183	            var nameEn = await FetchEnglishNameAsync(httpClient, course.Semester, course.Serial);
184	            if (nameEn is null)
185	                continue;
186	
187	            course.NameEn = nameEn;
188	            course.UpdatedAt = DateTime.UtcNow;
189	        }
190	
191	        await db.SaveChangesAsync();
192	    }
193	
194	    /// <summary>
195	    /// Lesson sync
196	    /// </summary>
197	    /// <param name="http"></param>
198	    /// <returns></returns>
199	    private async Task SyncLessonsAsync(HttpClient http)
200	    {
201	        await using var db = await _dbFactory.CreateDbContextAsync();
202	
203	        var courses = await db.Courses
204	            .Select(c => new { c.CourseKey, c.Semester, c.Serial })
205	            .ToListAsync();
206	
207	        foreach (var course in courses)
208	        {
209	            if (string.IsNullOrEmpty(course.Serial)) continue;
210	
211	            var semesterApi = ToApiSemester(course.Semester);
212	            var url = $"{_courseApiBase}/{_coursePath}?semester={semesterApi}&serial={course.Serial}&syllabus=true";
213	
214	            _logger.LogInformation("正在同步 {CourseKey} 的堂次 (serial={Serial})...", course.CourseKey, course.Serial);
215	
216	            NtuCourseResponse? response;
217	            try
218	            {
219	                response = await http.GetFromJsonAsync<NtuCourseResponse>(url);
220	            }
221	            catch (Exception ex)
222	            {
223	                _logger.LogWarning(ex, "無法取得 {CourseKey} 的課程資料", course.CourseKey);
224	                continue;
225	            }
226	
227	            await ClearLessonsAsync(db, course.CourseKey);
228	            await InsertLessonsAsync(db, course.CourseKey, semesterApi, response?.Syllabus?.Progress);
229	        }
230	    }
231	
232	    private async Task<string?> FetchEnglishNameAsync(HttpClient httpClient, string semester, string serial)
233	    {
234	        var semesterApi = ToApiSemester(semester);
235	        var url = $"{_courseNameEnApiBase}/{_coursePath}?semester={semesterApi}&serial={Uri.EscapeDataString(serial)}&lang=en_US";
236	        try
237	        {
238	            var response = await httpClient.GetFromJsonAsync<NtuCourseResponse>(url);
239	            return string.IsNullOrWhiteSpace(response?.Name) ? null : response.Name;
240	        }
241	        catch (Exception ex)
242	        {
243	            _logger.LogWarning(ex, "無法取得 serial={Serial} 的英文課程名稱", serial);
244	            return null;
245	        }
246	    }
247	
248	    // "1142" → "114-2"
249	    private static string ToApiSemester(string semester) =>
250	        semester.Length == 4 ? semester[..3] + "-" + semester[3..] : semester;
251	
252	    private async Task ClearLessonsAsync(AppDbContext db, string courseKey)
253	    {
254	        var toDelete = await db.Lessons.Where(l => l.CourseKey == courseKey).ToListAsync();
255	        if (toDelete.Count > 0)
256	        {
257	            db.Lessons.RemoveRange(toDelete);
258	            await db.SaveChangesAsync();
259	        }
260	    }
261	
262	    private async Task InsertLessonsAsync(AppDbContext db, string courseKey, string semesterApi, List<NtuProgressItem>? progress)
263	    {
264	        if (progress is null || progress.Count <= 0)
265	            return;
266	
267	        var rocYear = int.Parse(semesterApi[..3]);
268	        var semPart = semesterApi[^1] - '0';
269	        var gregorianYear = rocYear + 1911;
270	
271	        foreach (var item in progress)
272	        {
273	            if (!int.TryParse(item.Week, out var weekNum)) continue;
274	            var dates = ParseAllDates(item.Date, semPart, gregorianYear).ToList();
275	            if (dates.Count == 0) continue;
276	
277	            var topic = string.IsNullOrWhiteSpace(item.Content) ? "" : item.Content;
278	
279	            for (var i = 0; i < dates.Count; i++)
280	            {
281	                var lessonId = CourseHelper.BuildLessonId(courseKey, weekNum, dates[i]);
282	                var lessonDate = DateTime.SpecifyKind(dates[i], DateTimeKind.Utc);
283	
284	                db.Lessons.Add(new Lesson
285	                {
286	                    LessonId = lessonId,
287	                    CourseKey = courseKey,
288	                    WeekNumber = weekNum,
289	                    LessonDate = lessonDate,
290	                    Topic = topic
291	                });
292	            }
293	        }
294	
295	        await db.SaveChangesAsync();
296	    }
297	
298	    // Parses all dates from strings like "02/23, 02/25".
299	    // Year inferred from semester: spring (2) → gregorianYear; fall (1) → month >= 8 means previous Gregorian year.
300	    private static IEnumerable<DateTime> ParseAllDates(string? dateStr, int semPart, int gregorianYear)
301	    {
302	        if (string.IsNullOrWhiteSpace(dateStr)) yield break;
303	        foreach (var part in dateStr.Split(','))
304	        {
305	            var segments = part.Trim().Split('/');
306	            if (segments.Length != 2) continue;
307	            if (!int.TryParse(segments[0], out var month) || !int.TryParse(segments[1], out var day)) continue;
308	            var year = semPart == 2 ? gregorianYear : month >= 8 ? gregorianYear - 1 : gregorianYear;
309	            DateTime date;
310	            try { date = new DateTime(year, month, day); }
311	            catch { continue; }
312	            yield return date;
313	        }
314	    }
315	}
