84	    private static Dictionary<string, (NtuDeptItem? Zh, NtuDeptItem? En)> MergeById(
85	        List<NtuDeptItem> zhItems,
86	        List<NtuDeptItem> enItems)
87	    {
88	        var merged = new Dictionary<string, (NtuDeptItem? Zh, NtuDeptItem? En)>(StringComparer.Ordinal);
89	
90	        foreach (var item in zhItems)
91	        {
92	            var id = item.Id?.Trim();
93	            if (string.IsNullOrEmpty(id)) continue;
94	            merged[id] = (item, null);
95	        }
96	
97	        foreach (var item in enItems)
98	        {
99	            var id = item.Id?.Trim();
100	            if (string.IsNullOrEmpty(id)) continue;
101	            if (merged.TryGetValue(id, out var existing))
102	                merged[id] = (existing.Zh, item);
103	            else
104	                merged[id] = (null, item);
105	        }
106	
107	        return merged;
108	    }
109	
110	    private async Task UpsertAsync(Dictionary<string, (NtuDeptItem? Zh, NtuDeptItem? En)> merged)
111	    {
112	        await using var db = await _dbFactory.CreateDbContextAsync();
113	        var existing = await db.Departments.ToDictionaryAsync(d => d.DeptCode, StringComparer.Ordinal);
114	        var now = DateTime.UtcNow;
115	
116	        foreach (var (id, pair) in merged)
117	        {
118	            var deptCode = Truncate(id, MaxDeptCodeLength);
119	            var nameZh = Truncate(FirstNonEmpty(pair.Zh?.Name, pair.En?.Name), MaxNameLength);
120	            var nameEn = Truncate(FirstNonEmpty(pair.En?.Name, pair.Zh?.Name), MaxNameLength);
121	            if (string.IsNullOrEmpty(nameZh) && string.IsNullOrEmpty(nameEn))
122	                continue;
123	
124	            var shortZh = TruncateNullable(Normalize(pair.Zh?.ShortName), MaxShortNameLength);
125	            var shortEn = TruncateNullable(Normalize(pair.En?.ShortName), MaxShortNameLength);
126	
127	            if (!existing.TryGetValue(deptCode, out var row))
128	            {
129	                row = new Department
130	                {
131	                    DeptCode = deptCode,
132	                    CreatedAt = now,
133	                };
134	                db.Departments.Add(row);
135	                existing[deptCode] = row;
136	            }
137	
138	            row.NameZh = nameZh;
139	            row.NameEn = nameEn;
140	            row.ShortNameZh = shortZh;
141	            row.ShortNameEn = shortEn;
142	            row.UpdatedAt = now;
143	        }
144	
145	        await db.SaveChangesAsync();
146	    }
147	
148	    private static string FirstNonEmpty(string? primary, string? fallback)
149	    {
150	        if (!string.IsNullOrWhiteSpace(primary)) return primary.Trim();
151	        if (!string.IsNullOrWhiteSpace(fallback)) return fallback.Trim();
152	        return string.Empty;
153	    }
154	
155	    private static string? Normalize(string? value) =>
156	        string.IsNullOrWhiteSpace(value) ? null : value.Trim();
157	
158	    private static string Truncate(string value, int max) =>
159	        value.Length <= max ? value : value[..max];
160	
161	    private static string? TruncateNullable(string? value, int max) =>
162	        value is null ? null : Truncate(value, max);
163	
