171	    {
172	        [JsonPropertyName("id")]
173	        public string? Id { get; set; }
174	
175	        [JsonPropertyName("name")]
176	        public string? Name { get; set; }
177	
178	        [JsonPropertyName("shortName")]
179	        public string? ShortName { get; set; }
180	    }
181	}
