12	public static class SsoEndpoints {
13	    private const string AuthScheme = CookieAuthenticationDefaults.AuthenticationScheme;
14	
15	    public static void MapSsoApi(this IEndpointRouteBuilder app, bool enableTestCallback = false) {
16	        var group = app.MapGroup("/auth");
17	
18	        // NTU SSO
19	        group.MapGet("/login", async (HttpContext context, IOptions<FutureClassroomOptions> fcOpt) => {
20	            try {
21	                var callbackUrl = $"{fcOpt.Value.BaseUrl}auth/callback";
22	
23	                var props = new AuthenticationProperties { RedirectUri = callbackUrl };
24	                await context.ChallengeAsync(Saml2Defaults.Scheme, props);
25	            }
26	            catch {
27	                Results.Problem("Failed to initialize login flow.", statusCode: 500);
28	            }
29	        });
30	    
31	        group.MapGet("/callback", async Task<IResult> (HttpContext context, IOptions<FutureClassroomOptions> fcOpt) => {
32	            var result = await context.AuthenticateAsync(AuthScheme);
33	            if (!result.Succeeded)
34	                return ApiErrors.Unauthorized("SSO authentication failed.");
35	
36	            var claimsIdentity = result.Principal?.Identity as System.Security.Claims.ClaimsIdentity;
37	            var ntuAccountName = claimsIdentity?.FindFirst("http://www.ntu.edu.tw/AccountName")?.Value;
38	            var ntuChineseName = claimsIdentity?.FindFirst("http://www.ntu.edu.tw/ChineseName")?.Value;
39	            var ntuSeq = claimsIdentity?.FindFirst("http://www.ntu.edu.tw/SEQ")?.Value;
40	            var ntuTypeCode = claimsIdentity?.FindFirst("http://www.ntu.edu.tw/AccountTypeCode")?.Value;
41	            var ntuMajor = claimsIdentity?.FindFirst("http://www.ntu.edu.tw/UNITB")?.Value;
42	
43	            await SignInUserAsync(context, ntuAccountName ?? "", ntuChineseName ?? "台大使用者", ntuSeq ?? "", ntuTypeCode ?? "", ntuMajor ?? "", AuthScheme);
44	
45	            return Results.Redirect($"{fcOpt.Value.FrontendUrl}");
46	        });
47	            
48	        // 在開發環境模擬正式的 POST 回傳
49	        if (enableTestCallback) {
50	            group.MapPost("/test-callback", async (HttpContext context, IOptions<FutureClassroomOptions> fcOpt) => {
51	
52	                // 模擬從台大拿到的資料
53	                string mockAccount = "r14725046";
54	                string mockName = "陳書雁";
55	                string mockSeq = "r14725046";
56	                string mockTypeCode = "u";
57	                string mockMajor = "資訊管理學系";
58	
59	
60	                await SignInUserAsync(context, mockAccount, mockName, mockSeq, mockTypeCode, mockMajor, AuthScheme);
61	
62	                return Results.Ok(new {
63	                    status = "Success",
64	                    message = "Cookie 已發放，請造訪 /auth/me 確認",
65	                });
66	            });
67	        }
68	
69	        group.MapGet("/logout", async Task<IResult> (
70	            HttpContext context,
71	            IWebHostEnvironment env,
72	            IOptions<NtuSsoOptions> ssoOpt,
73	            IOptions<FutureClassroomOptions> fcOpt) => {
74	
75	            await context.SignOutAsync(AuthScheme);
76	
77	            var returnUrl = $"{fcOpt.Value.FrontendUrl}login";
78	
79	            if (env.IsDevelopment())
80	                return Results.Redirect(returnUrl); // 在本機開發時導回本地端登入頁
81	
82	            var logoutUrl = $"{ssoOpt.Value.BaseUrl}logout?url={Uri.EscapeDataString(returnUrl)}";
83	
84	            return Results.Redirect(logoutUrl);
85	        });
86	        
87	        group.MapGet("/me", async (HttpContext context, DepartmentService departments) => {
88	
89	            if (context.User.Identity?.IsAuthenticated != true) {
90	                return ApiErrors.Unauthorized();
91	            }
92	            var id = context.User.FindFirst("StudentId")?.Value;
93	            var name = context.User.FindFirst(ClaimTypes.Name)?.Value;
94	            var department = context.User.FindFirst("Major")?.Value;
95	            var role = context.User.FindFirst("UserType")?.Value;
96	
97	            var resolved = await departments.FindByMajorAsync(department);
98	
99	            return Results.Ok(new UserResponse(
100	                User: new UserInfo(
101	                    Id: id ?? "",
102	                    Name: name ?? "",
103	                    Department: department,
104	                    DepartmentZh: resolved?.NameZh ?? department,
105	                    DepartmentEn: resolved?.NameEn ?? department,
106	                    Role: role ?? ""
107	                )
108	            ));
109	        }); 
110	 
111	    }
112	
113	    private static string MapRole(string accountTypeCode) => accountTypeCode switch
114	    {
115	        "u" or "g" => "student",
116	        "f" => "teacher",
117	        _ => "consultant"
118	    };
119	
120	    private static async Task SignInUserAsync(HttpContext context, string account, string name, string seq, string typeCode, string major, string authScheme)
121	    {
122	        var claims = new List<Claim>
123	        {
124	            new Claim(ClaimTypes.NameIdentifier, account),
125	            new Claim(ClaimTypes.Name, name),
126	            new Claim("StudentId", account),
127	            new Claim("AccountSeq", seq),
128	            new Claim("UserType", MapRole(typeCode)),
129	            new Claim("Major", major)
130	        };
131	
132	        var identity = new ClaimsIdentity(claims, authScheme);
133	        await context.SignInAsync(authScheme, new ClaimsPrincipal(identity));
134	    }
135	}

