1	import https from "https";
2	import { NextRequest, NextResponse } from "next/server";
3	
4	// 自訂 HTTPS agent，開發環境忽略自簽憑證驗證
5	const agent = new https.Agent({
6	  rejectUnauthorized: process.env.NODE_ENV === "production",
7	});
8	
9	const NEXT_PUBLIC_API_URL = process.env.NEXT_PUBLIC_API_URL || "https://localhost:7113";
10	
11	function encodePathSegment(segment: string) {
12	  let current = segment;
13	  for (let i = 0; i < 2; i++) {
14	    try {
15	      const decoded = decodeURIComponent(current);
16	      if (decoded === current) break;
17	      current = decoded;
18	    } catch {
19	      break;
20	    }
21	  }
22	  return encodeURIComponent(current);
23	}
24	
25	async function proxyRequest(req: NextRequest, path: string[]) {
26	  // Next.js 會把 %20 解成空白；Kestrel 本機不一定會再解一次。
27	  // 每個 segment 先 decode 再 encode，讓轉發到後端的 URL 編碼一致。
28	  const targetPath = path.map(encodePathSegment).join("/");
29	  const targetUrl = new URL(`${NEXT_PUBLIC_API_URL}/${targetPath}`);
30	
31	  // 保留原始 query string
32	  req.nextUrl.searchParams.forEach((value, key) => {
33	    targetUrl.searchParams.set(key, value);
34	  });
35	
36	  const headers = new Headers(req.headers);
37	  // 移除 host header，避免後端驗證失敗
38	  headers.delete("host");
39	  headers.delete("accept-encoding");
40	
41	  const fetchOptions: RequestInit & { agent?: https.Agent; duplex?: string } = {
42	    method: req.method,
43	    headers,
44	    // @ts-ignore: agent 為 Node.js fetch 擴充屬性
45	    agent,
46	    // 不自動追蹤 redirect，讓瀏覽器自行處理（SAML2 SSO 轉址需要此設定）
47	    redirect: "manual",
48	    // GET / HEAD 不帶 body
49	    body:
50	      req.method !== "GET" && req.method !== "HEAD" ? req.body : undefined,
51	    duplex: "half",
52	  };
53	
54	  try {
55	    const response = await fetch(targetUrl.toString(), fetchOptions as RequestInit);
56	
57	    // 透傳 3xx redirect 給瀏覽器，讓瀏覽器執行跳轉（例如 SAML2 SSO 登入頁）
58	    if (response.status >= 300 && response.status < 400) {
59	      const location = response.headers.get("location");
60	      if (location) {
61	        const redirectRes = NextResponse.redirect(location, { status: response.status });
62	        // 必須一併轉發 Set-Cookie，否則 SAML2 state cookie 會遺失
63	        const setCookies = response.headers.getSetCookie?.() ?? [];
64	        for (const cookie of setCookies) {
65	          redirectRes.headers.append("set-cookie", cookie);
66	        }
67	        return redirectRes;
68	      }
69	    }
70	
71	    const resHeaders = new Headers(response.headers);
72	
73	    resHeaders.delete("content-encoding");
74	    resHeaders.delete("content-length");
75	
76	    // new Headers() 會把多顆 Set-Cookie 併成一條字串，造成登入 cookie 壞掉，
77	    // 所以改用 getSetCookie() append 回去。
78	    resHeaders.delete("set-cookie");
79	    for (const cookie of response.headers.getSetCookie?.() ?? []) {
80	      resHeaders.append("set-cookie", cookie);
81	    }
82	
83	    return new NextResponse(response.body, {
84	      status: response.status,
85	      statusText: response.statusText,
86	      headers: resHeaders,
87	    });
88	  } catch (err) {
89	    console.error(`[Proxy] Failed to reach ${targetUrl}:`, err);
90	    return NextResponse.json(
91	      { error: "Proxy error", detail: String(err) },
92	      { status: 502 }
93	    );
94	  }
95	}
