3	import {
4	  createContext,
5	  useCallback,
6	  useContext,
7	  useEffect,
8	  useState,
9	  type ReactNode,
10	} from "react";
11	import { usePathname } from "next/navigation";
12	
13	const ShowcaseEmptyContext = createContext(false);
14	
15	export function useShowcaseEmpty() {
16	  return useContext(ShowcaseEmptyContext);
17	}
18	
19	function syncEmptyQuery(empty: boolean) {
20	  const url = new URL(window.location.href);
21	  if (empty) url.searchParams.set("empty", "1");
22	  else url.searchParams.delete("empty");
23	  const next = `${url.pathname}${url.search}${url.hash}`;
24	  window.history.replaceState(window.history.state, "", next);
25	}
26	
27	function readEmptyFromLocation() {
28	  return new URLSearchParams(window.location.search).get("empty") === "1";
29	}
30	
31	export function ShowcaseModeProvider({ children }: { children: ReactNode }) {
32	  const pathname = usePathname();
33	  const [isEmpty, setIsEmpty] = useState(false);
34	
35	  useEffect(() => {
36	    setIsEmpty(readEmptyFromLocation());
37	  }, [pathname]);
38	
39	  const setEmpty = useCallback((empty: boolean) => {
40	    setIsEmpty(empty);
41	    syncEmptyQuery(empty);
42	  }, []);
43	
44	  const showToggle =
45	    pathname !== "/login" &&
46	    (process.env.NODE_ENV !== "production" ||
47	      process.env.NEXT_PUBLIC_SHOWCASE === "1");
48	
49	  return (
50	    <ShowcaseEmptyContext.Provider value={isEmpty}>
51	      {children}
52	      {showToggle && (
53	        <div className="fixed bottom-24 right-4 z-[200] md:bottom-4 flex items-center gap-1 rounded-full bg-white p-1 shadow-[0_8px_24px_rgba(6,45,65,0.16)]">
54	          <button
55	            type="button"
56	            onClick={() => setEmpty(true)}
57	            className={`h-8 px-3 rounded-full body-2-reg transition-colors ${
58	              isEmpty
59	                ? "bg-gray-90 text-white"
60	                : "text-gray-70 hover:bg-[rgba(6,45,65,0.05)]"
61	            }`}
62	          >
63	            Empty
64	          </button>
65	          <button
66	            type="button"
67	            onClick={() => setEmpty(false)}
68	            className={`h-8 px-3 rounded-full body-2-reg transition-colors ${
69	              !isEmpty
70	                ? "bg-gray-90 text-white"
71	                : "text-gray-70 hover:bg-[rgba(6,45,65,0.05)]"
72	            }`}
73	          >
74	            Loaded
75	          </button>
76	        </div>
77	      )}
78	    </ShowcaseEmptyContext.Provider>
79	  );
80	}
